#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

#define int long long
const int M1 = 998244353, M2 = 1000000007;
const int power[] = {1, 10, 100, 1000, 10000, 100000, 1000000};

int sum_vals[7], total_res, countA, maxN, countB;
vector<int> vecs[7];

void build(int depth, int val) {
    if (depth == 7) return;
    vecs[depth].push_back((countA - val + M1) % M1);
    sum_vals[depth] += (countA - val + M1) % M1;
    countA++;
    for (int digit = 0; digit <= 9; ++digit) {
        build(depth + 1, val * 10 + digit);
    }
}

bool in_range(int x) {
    return x * power[6] + 999999 <= maxN && x * power[6] * 10 > maxN;
}

void explore_all(int level, int current) {
    if (current > maxN) return;
    if (in_range(current)) {
        for (int i = 0; i <= 6; ++i) {
            int p = ((countB + 1 - (current * power[i])) % M1 + M1) % M1;
            int pos = (int)(lower_bound(vecs[i].begin(), vecs[i].end(), M1 - p) - vecs[i].begin());
            total_res = (total_res + (sum_vals[i] + p * vecs[i].size() - M1 * (vecs[i].size() - pos))) % M2;
        }
        countB += countA;
        return;
    }
    countB++;
    total_res = (total_res + ((countB - current) % M1 + M1) % M1) % M2;
    for (int digit = (level == 0 ? 1 : 0); digit <= 9; ++digit) {
        explore_all(level + 1, current * 10 + digit);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> maxN;
    build(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(vecs[i].begin(), vecs[i].end());
    }
    countB = -1;
    explore_all(0, 0);
    cout << total_res << '\n';
    return 0;
}
